def recipe_dial_value(dial, value):
    """One declared dial on the way in: a listed choice or finite in-range
    number passes, with numbers coerced the way the builder coerces so the
    stored spec says what ran. Anything else lands on the recipe constant.
    Degrades, never dies - the same policy as reroll's canvas block."""
    if dial.get("kind") == "choice":
        return _recipe_choice_value(dial, value)
    if isinstance(value, bool) or not isinstance(value, (int, float)) \
            or not math.isfinite(value) \
            or value < dial["min"] or value > dial["max"]:
        return dial["default"]
    return int(value) if isinstance(dial["default"], int) else float(value)


def _recipe_dials_payload(spec):
    """The extender's declared dials, with choice dials carrying their LIVE
    options: the scan runs here so only installed variants are ever offered
    (brief 9.15) - never a variant that would fail at queue time. The choice
    label is the count itself ("2-vector"), keyed on the tensor, and `name`
    is the loader-listed rel the graph will actually load."""
    out = []
    for dial in spec.get("dials", []):
        d = dict(dial)
        if d.get("choices_from") == "vector_bypass":
            d["choices"] = [{"value": count, "label": f"{count}-vector",
                             "name": rel}
                            for count, rel in sorted(vector_bypass_variants().items())]
        elif d.get("choices_from") == "identity_patch":
            # The build's own name IS the label ("Full" / "r128" / "r64") -
            # three sized labels measurably overflow the card drawer, whose
            # grid control cannot shrink below its own labels, so the build's
            # weight on disk rides the option TITLE instead (brief 9.56).
            sizes = {e["rel"]: e.get("size") or 0
                     for e in model_catalog("loras")}
            d["choices"] = [{"value": build,
                             "label": "Full" if build == "full" else build,
                             "name": rel,
                             "title": f"{_identity_size_label(sizes.get(rel))}"
                                      f" · {rel}"}
                            for build, rel in identity_patch_variants().items()]
        out.append(d)
    return out


def _recipe_choice_value(dial, value):
    """A declared choice passes only when it names one of its options.

    Dynamic choices validate against what is installed, so a stale composer
    degrades to the authored default rather than failing at queue time. Static
    inline choices validate against their declaration. The default itself
    always passes, and choice values keep their declared type."""
    if value == dial["default"]:
        return value
    source = dial.get("choices_from")
    if source == "vector_bypass":
        if isinstance(value, bool) or not isinstance(value, (int, float)) \
                or not math.isfinite(value) or value != int(value):
            return dial["default"]
        value = int(value)
        installed = vector_bypass_variants()
    elif source == "identity_patch":
        installed = identity_patch_variants()
    elif "choices" in dial:
        return value if any(
            isinstance(choice, dict) and choice.get("value") == value
            for choice in dial.get("choices") or ()) else dial["default"]
    else:
        installed = {}
    return value if value in installed else dial["default"]
